childElements.propertySetConfig:
{
  "sanitize" : false,
  "textKey" : "",
  "HTMLTemplateId" : "",
  "dataJSON" : false,
  "show" : {
    "group" : {
      "operator" : "AND",
      "rules" : [ {
        "data" : "Branch staff unhelpful",
        "condition" : "=",
        "field" : "ApologiseBranchQueue:TalkTrackApologise:selectedButtonName"
      } ]
    }
  },
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<p><strong>Apologise to the customer:</strong></p>\n<p>&nbsp;</p>\n<p>&ldquo;I&rsquo;m sorry to hear that. We certainly don&rsquo;t want our customers to feel that way.&rdquo;</p>\n<p>OR</p>\n<p>&ldquo;I&rsquo;m sorry to hear you&rsquo;ve had that experience.&rdquo;</p>\n<p>&nbsp;</p>\n<p><strong>Acknowledge concern:</strong></p>\n<p>&nbsp;</p>\n<p>&ldquo;Thank you for raising this with us. I&rsquo;ve recorded your concerns and this will be considered as part of our internal review.&rdquo;</p>\n<p>AND/OR</p>\n<p>&ldquo;Please be assured that we do review complaints to ensure we maintain appropriate service levels.&rdquo;</p>\n<p>AND/OR</p>\n<p>&ldquo;Your complaint is reported internally to show what training and support is needed for our staff.&rdquo;</p>\n</div>",
  "label" : "TextBlock1",
  "controlWidth" : 12
}

