{
  "sanitize" : false,
  "textKey" : "",
  "HTMLTemplateId" : "",
  "dataJSON" : false,
  "show" : {
    "group" : {
      "operator" : "AND",
      "rules" : [ {
        "data" : "General branch wait time",
        "condition" : "=",
        "field" : "ApologiseBranchQueue:TalkTrackApologise:selectedButtonName"
      } ]
    }
  },
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<p><strong>Apologise to the customer:</strong></p>\n<p>&nbsp;</p>\n<p>&ldquo;I&rsquo;m sorry for the inconvenience. I know that your time is valuable and extended wait times can be frustrating.&rdquo;</p>\n<p>&nbsp;</p>\n<p>OR</p>\n<p>&nbsp;</p>\n<p>&ldquo;I&rsquo;m sorry about this. I understand it&rsquo;s not easy to find time in the day to visit a branch.&rdquo;</p>\n<p>&nbsp;</p>\n<p><strong>Acknowledge concern:</strong></p>\n<p>&nbsp;</p>\n<p>&ldquo;Thank you for raising this with us. I&rsquo;ve recorded your concerns and this will be considered as part of our internal review.&rdquo;</p>\n</div>",
  "label" : "TextBlock1",
  "controlWidth" : 12
}

