    "source" : "%ApologiseBranchQueue:TalkTrackConfirm:selectedButtonName%"
  } ],
  "bStandalone" : false,
  "lwcName" : "customRadiobuttonWithIcon",
  "hide" : false,
  "conditionType" : "Hide if False",
  "show" : null,
  "label" : "TalkTrackApologise",
  "controlWidth" : 12
}

{
  "controlWidth" : 12,
  "label" : "TextBlock1",
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<p><strong>Ask further questions (if relevant) to confirm complaint details, such as:</strong></p></br>\n<p>&ldquo;Can you tell me more about what happened?&rdquo;<br />&ldquo;I understand that you weren&rsquo;t happy that &lt;the ATM wasn&rsquo;t working/ANZ has removed an ATM&gt;, is that right?&rdquo;<br />&ldquo;Can you confirm the street name, location, or branch where this ATM was?&rdquo;<br />&ldquo;Would you like me to help you find your nearest alternative ATM?&rdquo;</p>\n</div>",
  "show" : {
    "group" : {
      "operator" : "AND",
      "rules" : [ {
        "data" : "ATM unavailable",
        "condition" : "=",
        "field" : "ConfirmBranchQueue:TalkTrackConfirm:selectedButtonName"
      } ]
    }
  },
  "dataJSON" : false,
  "HTMLTemplateId" : "",
  "textKey" : "",
  "sanitize" : false
}

{
  "controlWidth" : 12,
  "label" : "TextBlock1",
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<p><strong>Ask further questions (if relevant) to confirm complaint details, such as:</strong></p></br>\n<p>&ldquo;Can you tell me more about your concerns?&rdquo;<br />&ldquo;I understand that you weren&rsquo;t happy &lt;with ANZ&rsquo;s decision to close a branch/that there aren&rsquo;t enough ANZ branches&gt;, is that right?&rdquo;<br />&ldquo;Would you like me to help you check where your nearest alternative branch or ATMs are?&rdquo;<br />&ldquo;What do you normally need to do at your branch?&rdquo;</p>\n</div>",
  "show" : {
